from typing import List, Dict, Any, Tuple

SAFETY_DISCLAIMER = (
    "ENGINEERING SAFETY NOTICE: This preliminary assessment is generated by an automated computer vision screening model. "
    "Visual assessment alone CANNOT establish structural load-bearing integrity or material compliance with ASTM / ISO / IS building codes. "
    "All safety-critical structural materials must undergo formal non-destructive testing (NDT), laboratory verification, and certified sign-off by a licensed structural engineer before field reuse."
)

class ConditionRecommender:
    """
    Intelligent Condition Classification and Reusability Recommendation Engine.
    Evaluates:
    - Detected defect severity count (High, Medium, Low)
    - Structural criticality of material category
    - Material-specific recovery & circular construction economics
    """

    SAFETY_CRITICAL_MATERIALS = [
        "Steel rods / Reinforcement bars",
        "Concrete blocks",
        "Pipes"
    ]

    def evaluate(
        self,
        material_category: str,
        material_confidence: float,
        defects: List[Dict[str, Any]],
        image_blur_metric: float = 80.0
    ) -> Dict[str, Any]:
        """
        Determines:
        - condition (GOOD, DAMAGED, INSPECTION REQUIRED)
        - condition_score (0.0 - 100.0)
        - recommendation (REUSE, INSPECT, REPAIR, RECYCLE, REJECT)
        - recommendation_reason
        - suggested_next_step
        """
        # Tally defect severities
        high_count = sum(1 for d in defects if d.get("severity") == "High")
        med_count = sum(1 for d in defects if d.get("severity") == "Medium")
        low_count = sum(1 for d in defects if d.get("severity") == "Low")
        total_defects = len(defects)

        # 1. Calculate numerical condition score (0 - 100)
        base_score = 100.0
        base_score -= (high_count * 34.0)
        base_score -= (med_count * 16.0)
        base_score -= (low_count * 6.0)

        # Confidence penalty if confidence is somewhat low
        if material_confidence < 70.0:
            base_score -= (70.0 - material_confidence) * 0.4

        condition_score = round(max(5.0, min(100.0, base_score)), 1)

        # 2. Determine Condition Classification
        # Case A: Inspection Required (borderline or low confidence)
        if material_confidence < 62.0 or (total_defects > 0 and 55.0 <= condition_score <= 68.0 and material_category in self.SAFETY_CRITICAL_MATERIALS):
            condition = "INSPECTION REQUIRED"
        # Case B: Good condition (minimal or no defects)
        elif high_count == 0 and med_count == 0 and low_count <= 1 and condition_score >= 80.0:
            condition = "GOOD"
        # Case C: Damaged
        else:
            condition = "DAMAGED"

        # 3. Determine Reusability Recommendation
        # REUSE, INSPECT, REPAIR, RECYCLE, REJECT
        defect_names = [d.get("name", "").lower() for d in defects]
        has_crack = any("crack" in name or "fracture" in name for name in defect_names)
        has_rust = any("rust" in name or "corrosion" in name for name in defect_names)
        has_spalling = any("spall" in name for name in defect_names)
        has_rot = any("rot" in name for name in defect_names)
        has_deformation = any("deformation" in name or "bend" in name for name in defect_names)
        has_broken_edge = any("broken" in name or "chip" in name for name in defect_names)

        if condition == "GOOD":
            recommendation = "REUSE"
            reason = (
                f"No significant structural defects or surface deterioration detected in {material_category}. "
                f"Visual condition score is {condition_score}/100 with high confidence ({material_confidence}%)."
            )
            next_step = "Proceed with standard on-site physical count, dimensional verification, and direct reuse in approved project works."

        elif condition == "INSPECTION REQUIRED":
            recommendation = "INSPECT"
            reason = (
                f"Visual features show borderline anomalies or detection confidence ({material_confidence}%) requires physical validation. "
                f"For {material_category}, automated visual screening alone is inconclusive for immediate reuse authorization."
            )
            next_step = "Route item to Senior Quality Inspector for physical non-destructive testing (NDT), ultrasonic or Schmidt hammer test before decision."

        else: # condition == "DAMAGED"
            # Material-specific remediation logic
            if material_category == "Steel rods / Reinforcement bars":
                if has_deformation or high_count > 0:
                    recommendation = "RECYCLE"
                    reason = "Significant structural deformation or severe deep-pitting corrosion detected. Load-bearing tensile capacity is compromised."
                    next_step = "Segregate from structural inventory. Dispatch to certified metal scrap recycling facility for remelting."
                elif has_rust:
                    recommendation = "REPAIR"
                    reason = "Surface oxidation/rust detected without severe cross-sectional loss. Bar remains dimensionally viable."
                    next_step = "Perform mechanical wire brushing or sandblasting followed by rust-converting primer before re-inspecting for non-critical slab or mesh use."
                else:
                    recommendation = "REJECT"
                    reason = "Visible mechanical damage observed on rebar."
                    next_step = "Reject from primary load-bearing staging area."

            elif material_category in ["Concrete blocks", "Bricks"]:
                if has_crack and high_count > 0:
                    recommendation = "RECYCLE"
                    reason = "Through-thickness fracture or major shear crack detected. Masonry unit cannot carry rated compressive load."
                    next_step = "Crush using mobile jaw crusher for use as recycled aggregate, sub-base gravel, or permeable paving fill."
                elif has_broken_edge or (med_count <= 2 and high_count == 0):
                    recommendation = "REPAIR"
                    reason = "Localized corner chipping or superficial edge notch detected. Core block body remains sound."
                    next_step = "Approved for secondary non-loadbearing partitions, landscape dwarf walls, or trim cut pieces."
                else:
                    recommendation = "REJECT"
                    reason = "Multiple fractures and extensive surface deterioration observed."
                    next_step = "Condemn unit and divert to site rubble sorting skip."

            elif material_category == "Wooden planks":
                if has_rot:
                    recommendation = "REJECT"
                    reason = "Fungal decay / timber rot detected. Biological degradation cannot be reversed and compromises timber fiber strength."
                    next_step = "Dispose of in accordance with bio-waste regulations to prevent fungal contagion to adjacent stored lumber."
                elif has_crack or has_broken_edge:
                    recommendation = "REPAIR"
                    reason = "Longitudinal end split or localized fiber cracking identified. Main board section remains structurally viable."
                    next_step = "Cross-cut and trim damaged end sections by ~15-20cm; plane edges and treat with timber preservative seal."
                else:
                    recommendation = "RECYCLE"
                    reason = "Surface degradation unsuitable for architectural timber."
                    next_step = "Divert to wood chipper for engineered mulch, MDF fiber, or non-structural composite manufacturing."

            elif material_category == "Tiles":
                if has_crack or high_count > 0:
                    recommendation = "RECYCLE"
                    reason = "Fractured ceramic/porcelain tile cannot be laid in standard continuous floor surfaces."
                    next_step = "Crush for decorative mosaic pathways, terrazzo binder aggregate, or landscaping bed infill."
                elif has_broken_edge or low_count > 0:
                    recommendation = "REPAIR"
                    reason = "Minor corner chip or surface scratch detected."
                    next_step = "Reserve for edge boundary cuts, perimeter borders, or utility room skirting where full tile is not required."
                else:
                    recommendation = "REJECT"
                    reason = "Unsuitable surface finish."
                    next_step = "Divert to ceramic recycling."

            elif material_category == "Pipes":
                if has_crack or has_deformation:
                    recommendation = "REJECT"
                    reason = "Crack or out-of-round deformation detected. Pipe will fail hydraulic pressure or soil overburden load."
                    next_step = "Mark defective and prevent installation in pressurized or concealed drainage lines."
                else:
                    recommendation = "REPAIR"
                    reason = "Surface corrosion or sediment encrustation observed."
                    next_step = "Flush, hydro-jet, and inspect joint O-rings before reusing in low-pressure open drainage."

            elif material_category in ["Sand", "Aggregates"]:
                if high_count > 0:
                    recommendation = "REJECT"
                    reason = "Excessive contamination or organic debris detected in bulk material."
                    next_step = "Do not use for concrete batching. Relegate to bulk fill or landscaping earthworks."
                else:
                    recommendation = "INSPECT"
                    reason = "Moisture clumping or grading variance detected."
                    next_step = "Perform on-site sieve analysis and silt content bottle test."

            else:
                # Default fallback for other damaged materials
                if high_count > 0:
                    recommendation = "REJECT"
                    reason = f"Severe defects detected in {material_category}."
                    next_step = "Quarantine material and verify disposal or secondary salvage pathway."
                else:
                    recommendation = "REPAIR"
                    reason = f"Manageable superficial defects identified in {material_category}."
                    next_step = "Carry out surface remediation and re-inspect."

        return {
            "condition": condition,
            "condition_score": condition_score,
            "recommendation": recommendation,
            "recommendation_reason": reason,
            "suggested_next_step": next_step,
            "safety_disclaimer": SAFETY_DISCLAIMER
        }
